        reversedSentence.append(reversedWord.toString());
        reversedSentence.append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().replaceAll("( )+", " ").trim();
}

public static String reverseWords(String s) {
    StringBuilder result = new StringBuilder();

    // Skip leading spaces and get the first word
    int firstSpace = s.indexOf(' ');
    int firstWord = firstSpace > 0 ? firstSpace + 1 : 0;

    while (firstWord < s.length()) {
        // Find the next space
        int nextSpace = s.indexOf(' ', firstWord);
        int wordLength = nextSpace > 0 ? nextSpace - firstWord : s.length() - firstWord;

        // Reverse the word
        for (int i = wordLength - 1; i >= 0; i--) {
            result.append(s.charAt(firstWord + i));
        }

        // Add a space if there are more words
        if (nextSpace > 0) {
            result.append(' ');
        }

        // Get the next word
        firstWord = nextSpace > 0 ? nextSpace + 1 : s.length();
    }

    return result.toString();
}

